function interact(){if(!started)return;let nearest=null,nd=Infinity;for(let o of [...trees,...stones.filter(s=>!s.taken),...plants.filter(p=>!p.taken),...loot]){let d=dist(player,o);if(d<nd){nd=d;nearest=o}}if(!cave&&dist(player,caveEntrance)<100){cave=true;player.x=1500;player.y=1500;toast('YOU DESCEND INTO THE DARK');if(!caveBoss){caveBoss={x:1640,y:1410,hp:260,max:260,boss:true,attack:0};enemies.push(caveBoss);loot.push({x:1320,y:1570,kind:'chest',taken:false})}return}if(cave&&player.y>2220){cave=false;player.x=1500;player.y=560;toast('DAYLIGHT, AT LAST');return}if(nearest&&nd<100){if(nearest.t!==undefined){nearest.taken=true;player.wood+=2+Math.floor(Math.random()*3);toast('GATHERED WOOD')}else if(nearest.kind==='stone'||nearest.kind==='ore'){nearest.taken=true;player.stone+=nearest.kind==='ore'?2:1;if(Math.random()<.25)player.crystal++;toast(nearest.kind==='ore'?'CAVE ORE · A STRANGE GLINT':'GATHERED STONE')}else if(nearest.kind==='berry'||nearest.kind==='herb'){nearest.taken=true;player[nearest.kind==='berry'?'berries':'herbs']+=nearest.kind==='berry'?2:1;toast(nearest.kind==='berry'?'WILD BERRIES GATHERED':'MEDICINAL HERBS GATHERED')}else if(nearest.kind==='chest'){nearest.taken=true;player.crystal+=2;player.stone+=4;toast('HEARTSTONE FOUND · THE CAVE WARDEN STIRS')}else if(nearest.kind==='crystal'){nearest.taken=true;player.crystal++;toast('HEARTSTONE FRAGMENT')}refresh();objective()}else if(nearest&&nd<145){toast('MOVE CLOSER TO GATHER')}else toast('NOTHING TO GATHER NEARBY')}
function attack(){if(!started||dead||attackCd>0)return;attackCd=.48;player.facing.x=keys.a?-1:keys.d?1:player.facing.x;let target=null,best=Infinity;for(let e of enemies){if(e.hp<=0)continue;let d=dist(player,e);if(d<player.range+(e.boss?30:0)&&d<best){best=d;target=e}}if(target){target.hp-=player.damage;target.flash=.13;if(target.hp<=0){if(target.boss){player.crystal+=3;toast('THE WARDEN FALLS · HEARTSTONE +3')}else{player.meat++;if(Math.random()<.4)player.herbs++;toast('HOSTILE DOWN · SALVAGE RECOVERED')}refresh();objective()}}else toast('SWING · NO TARGET IN REACH')}
function spawnEnemy(){if(cave){if(!caveBoss&&Math.random()<.3)return;let a=rand(0,6.28),r=rand(330,490);enemies.push({x:clamp(player.x+Math.cos(a)*r,1150,1850),y:clamp(player.y+Math.sin(a)*r,1150,2070),hp:62,max:62,speed:rand(42,65),attack:0,flash:0,boss:false});return}let a=rand(0,6.28),r=rand(390,570);enemies.push({x:clamp(player.x+Math.cos(a)*r,50,2950),y:clamp(player.y+Math.sin(a)*r,50,2550),hp:70,max:70,speed:rand(45,76),attack:0,flash:0,boss:false})}
function update(dt){if(!started||dead||paused)return;attackCd=Math.max(0,attackCd-dt);invuln=Math.max(0,invuln-dt);toastTimer-=dt;if(toastTimer<=0)document.querySelector('#toast').classList.remove('show');clock+=dt*.04;if(clock>=24){clock-=24;day++;toast(`DAY ${String(day).padStart(2,'0')} · KEEP MOVING`)}player.hunger=clamp(player.hunger-dt*.42,0,100);player.thirst=clamp(player.thirst-dt*.62,0,100);if(player.hunger<=0||player.thirst<=0)player.hp-=dt*1.6;
let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(dx||dy){let l=Math.hypot(dx,dy);player.x+=dx/l*player.speed*dt;player.y+=dy/l*player.speed*dt;player.facing={x:dx/l,y:dy/l}}if(cave){player.x=clamp(player.x,1150,1850);player.y=clamp(player.y,1130,2240)}else{player.x=clamp(player.x,35,2965);player.y=clamp(player.y,35,2565)}
if(!cave){spawnTimer-=dt;if(spawnTimer<=0){if(enemies.filter(e=>!e.boss&&e.hp>0).length<4)spawnEnemy();spawnTimer=rand(12,21)}}
for(let e of enemies){if(e.hp<=0)continue;e.attack-=dt;let d=dist(player,e);if(d>(e.boss?68:32)){let v=e.boss?70:e.speed;e.x+=(player.x-e.x)/d*v*dt;e.y+=(player.y-e.y)/d*v*dt}else if(e.attack<=0&&invuln<=0){player.hp-=e.boss?17:11;invuln=.68;e.attack=e.boss?1.2:1.55;toast(e.boss?'THE WARDEN STRIKES':'YOU ARE HIT · FIGHT BACK')}}
for(let s of structures){if(s.kind==='spikes'){for(let e of enemies)if(e.hp>0&&dist(s,e)<38)e.hp-=dt*16}if(s.kind==='fire'&&dist(s,player)<115)player.hp=clamp(player.hp+dt*1.1,0,100)}enemies.splice(0,enemies.length,...enemies.filter(e=>e.hp>0||e.boss&&e.hp>0));if(player.hp<=0){player.hp=0;dead=true;document.querySelector('#overlay').classList.remove('hidden');document.querySelector('.tag').textContent='FIELD NOTES · END OF ENTRY';document.querySelector('.intro h1').innerHTML='THE<br><em>FOREST</em><br>KEEPS YOU';document.querySelector('.intro p').textContent='The hollow goes quiet. Your story ends here, but the woods will remember.';document.querySelector('#startBtn').textContent='TRY AGAIN →'}refresh();objective()}
function plantBuild(x,y){if(!buildMode)return;let b=buildMode;if(Math.hypot(player.x-x,player.y-y)>170){toast('TOO FAR · BUILD NEAR YOURSELF');return}if(structures.some(s=>dist(s,{x,y})<60)){toast('TOO CLOSE TO ANOTHER STRUCTURE');return}structures.push({x,y,kind:b.kind});buildMode=null;toast(`${b.name} BUILT`);refresh();objective()}
canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('pointerdown',e=>{if(buildMode){let c=screenToWorld(e.clientX,e.clientY);plantBuild(c.x,c.y)}});
function screenToWorld(sx,sy){let cam=camera();return {x:sx+cam.x-W/2,y:sy+cam.y-H/2}}
function camera(){return {x:player.x,y:player.y}}
function rounded(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
function drawTree(t,cx,cy){let x=t.x-cx+W/2,y=t.y-cy+H/2;if(x<-70||x>W+70||y<-90||y>H+70)return;let r=t.r;ctx.fillStyle='rgba(4,10,6,.29)';ctx.beginPath();ctx.ellipse(x+7,y+18,r*1.15,r*.57,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#594b34';ctx.fillRect(x-4,y-8,8,27);let colors=['#203b2b','#294832','#31533a','#385c3e'];ctx.fillStyle=colors[Math.floor(t.t*4)];ctx.beginPath();ctx.arc(x,y-8,r,0,Math.PI*2);ctx.fill();ctx.fillStyle='rgba(157,185,112,.12)';ctx.beginPath();ctx.arc(x-r*.2,y-r*.35,r*.53,0,Math.PI*2);ctx.fill();ctx.fillStyle='#395b3d';ctx.beginPath();ctx.arc(x-r*.73,y+1,r*.48,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(x+r*.68,y+1,r*.45,0,Math.PI*2);ctx.fill()}
function drawWorld(){let c=camera(),darkness=clamp((clock-18)/6,0,1)*.52+clamp((6-clock)/6,0,1)*.36;ctx.fillStyle=cave?'#27251e':'#42583b';ctx.fillRect(0,0,W,H);if(cave){ctx.fillStyle='#3c3429';ctx.fillRect(0,0,W,H);for(let i=0;i<36;i++){let x=(i*173+42)%W,y=(i*271+30)%H;ctx.fillStyle=i%2?'#504332':'#392f26';ctx.beginPath();ctx.ellipse(x,y,rand(14,32),rand(10,25),0,0,Math.PI*2);ctx.fill()}ctx.strokeStyle='#716148';ctx.lineWidth=7;ctx.strokeRect(W/2-270,H/2-240,540,470);}
else{ctx.fillStyle='#526745';for(let i=0;i<22;i++){let x=(i*193-(c.x*.14)%193+W)%W,y=(i*127-(c.y*.14)%127+H)%H;ctx.beginPath();ctx.ellipse(x,y,100,52,.35,0,Math.PI*2);ctx.fill()}for(let i=0;i<42;i++){let wx=(i*83+21)%3000,wy=(i*127+13)%2600,x=wx-c.x+W/2,y=wy-c.y+H/2;if(x>-20&&x<W+20&&y>-20&&y<H+20){ctx.fillStyle=i%2?'#69734b':'#73764c';ctx.beginPath();ctx.ellipse(x,y,2,1.3,0,0,Math.PI*2);ctx.fill()}}// cave entrance
let ex=caveEntrance.x-c.x+W/2,ey=caveEntrance.y-c.y+H/2;ctx.fillStyle='#191b17';ctx.beginPath();ctx.ellipse(ex,ey,63,29,0,Math.PI,0);ctx.lineTo(ex+63,ey+8);ctx.ellipse(ex,ey+8,63,28,0,0,Math.PI);ctx.fill();ctx.fillStyle='#ae8854';ctx.font='10px monospace';ctx.textAlign='center';ctx.fillText('CAVE',ex,ey+43)}
// draw resource nodes
for(let o of [...stones.filter(s=>!s.taken),...plants.filter(p=>!p.taken),...loot.filter(l=>!l.taken)]){let x=o.x-c.x+W/2,y=o.y-c.y+H/2;if(x<-40||x>W+40||y<-40||y>H+40)continue;if(o.kind==='stone'||o.kind==='ore'){ctx.fillStyle=o.kind==='ore'?'#77785c':'#77756b';ctx.beginPath();ctx.ellipse(x,y,o.r,o.r*.65,.2,0,7);ctx.fill();ctx.fillStyle=o.kind==='ore'?'#d9bd6c':'#aaa99a';ctx.beginPath();ctx.ellipse(x-4,y-3,4,2,0,0,7);ctx.fill()}else if(o.kind==='berry'||o.kind==='herb'){ctx.fillStyle=o.kind==='berry'?'#768b52':'#a0a968';ctx.beginPath();ctx.arc(x,y,6,0,7);ctx.fill();if(o.kind==='berry'){ctx.fillStyle='#9f4d45';ctx.beginPath();ctx.arc(x+4,y-3,2,0,7);ctx.fill()}}else{ctx.fillStyle='#d3b563';ctx.fillRect(x-8,y-7,16,14);ctx.fillStyle='#59412b';ctx.fillRect(x-5,y-4,10,8)}}
for(let s of structures){let x=s.x-c.x+W/2,y=s.y-c.y+H/2;if(s.kind==='fire'){ctx.fillStyle='#30251c';ctx.beginPath();ctx.ellipse(x,y+5,23,10,0,0,7);ctx.fill();ctx.fillStyle='#e99a46';ctx.beginPath();ctx.moveTo(x,y-18);ctx.quadraticCurveTo(x+17,y,x,y+5);ctx.quadraticCurveTo(x-15,y-4,x,y-18);ctx.fill();ctx.fillStyle='#ffe39c';ctx.beginPath();ctx.ellipse(x,y-3,5,8,0,0,7);ctx.fill()}else if(s.kind==='shelter'){ctx.fillStyle='#765536';ctx.beginPath();ctx.moveTo(x-36,y+17);ctx.lineTo(x,y-22);ctx.lineTo(x+36,y+17);ctx.closePath();ctx.fill();ctx.fillStyle='#ad8953';ctx.fillRect(x-31,y+12,62,7)}else{ctx.fillStyle='#8c8268';for(let i=-2;i<=2;i++){ctx.beginPath();ctx.moveTo(x+i*10,y+12);ctx.lineTo(x+i*10+6,y-12);ctx.lineTo(x+i*10+12,y+12);ctx.fill()}}}
for(let e of enemies){if(e.hp<=0)continue;let x=e.x-c.x+W/2,y=e.y-c.y+H/2;if(e.boss){let glow=ctx.createRadialGradient(x,y,2,x,y,100);glow.addColorStop(0,'#e28b4b55');glow.addColorStop(1,'#e28b4b00');ctx.fillStyle=glow;ctx.fillRect(x-100,y-100,200,200)}ctx.fillStyle=e.flash>0?'#ead6a9':e.boss?'#803e35':'#725046';ctx.beginPath();ctx.ellipse(x,y,e.boss?22:14,e.boss?28:18,0,0,7);ctx.fill();ctx.fillStyle='#b8aa82';ctx.beginPath();ctx.arc(x,y-17,e.boss?12:8,0,7);ctx.fill();ctx.fillStyle='#df7354';ctx.fillRect(x-5,y-19,3,2);ctx.fillRect(x+3,y-19,3,2);ctx.fillStyle='#151710';ctx.fillRect(x-15,y-(e.boss?45:33),30,4);ctx.fillStyle='#bd654e';ctx.fillRect(x-15,y-(e.boss?45:33),30*e.hp/e.max,4);if(e.boss)document.querySelector('#bossbar').classList.toggle('visible',dist(player,e)<570&&e.hp>0);e.flash=Math.max(0,e.flash-dt0)}
for(let t of trees)drawTree(t,c.x,c.y);
// player shadow and body
let px=W/2,py=H/2;ctx.fillStyle='#10150f88';ctx.beginPath();ctx.ellipse(px+2,py+13,15,7,0,0,7);ctx.fill();ctx.fillStyle=invuln>0&&Math.floor(performance.now()/90)%2?'#f2c9a0':'#c6a47e';ctx.beginPath();ctx.arc(px,py-5,8,0,7);ctx.fill();ctx.fillStyle='#526a4a';ctx.beginPath();ctx.ellipse(px,py+7,10,13,0,0,7);ctx.fill();ctx.strokeStyle='#bd9a70';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(px+player.facing.x*7,py+2);ctx.lineTo(px+player.facing.x*22,py-7);ctx.stroke();if(attackCd>.28){ctx.strokeStyle='#e1d09f99';ctx.lineWidth=3;ctx.beginPath();ctx.arc(px,py,player.range*.5,-.9,.9);ctx.stroke()}
// proximity markers
if(!cave&&dist(player,caveEntrance)<190){ctx.fillStyle='#e3ddba';ctx.font='11px monospace';ctx.textAlign='center';ctx.fillText('E  DESCEND',W/2,H/2-37)}
if(buildMode){let x=mouse.x,y=mouse.y;ctx.globalAlpha=.6;ctx.strokeStyle='#dbeaa8';ctx.setLineDash([6,4]);ctx.beginPath();ctx.arc(x,y,22,0,7);ctx.stroke();ctx.setLineDash([]);ctx.globalAlpha=1}
if(darkness>0&&!cave){ctx.fillStyle=`rgba(11,18,14,${darkness})`;ctx.fillRect(0,0,W,H);let glow=ctx.createRadialGradient(W/2,H/2,50,W/2,H/2,350);glow.addColorStop(0,'#d9b86622');glow.addColorStop(1,'#111a1400');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H)}
if(cave){let grad=ctx.createRadialGradient(W/2,H/2,55,W/2,H/2,Math.min(W,H)*.68);grad.addColorStop(0,'#0c0d0b00');grad.addColorStop(1,'#080a09ee');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H)}
}

